"use client";

import type { ComponentProps } from "react";

import { Shutter } from "@/components/shutter";

/** Medium slat thickness. Color: Dark. */
export function ShutterSlatMediumDark(props: ComponentProps<typeof Shutter>) {
  return (
    <Shutter
      size="md"
      slatSize="medium"
      defaultLevel={60}
      variant="dark"
      label="Medium slats · Dark"
      {...props}
    />
  );
}
